      <style>{`.vm-icon {
  width: 36px;
  height: 36px;
  overflow: visible;
  stroke: #f4f4f5;
  stroke-width: 2px;
  stroke-linecap: round;
  stroke-linejoin: round;
  fill: none;
  transition: transform 0.38s cubic-bezier(0.34, 1.56, 0.64, 1), stroke 0.38s ease;
}
.vm-icon.is-open {
  stroke: #6366f1;
}
.vm-icon * {
  transform-box: view-box;
